/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input logic clk,
    input logic reset,
    input logic s,
    input logic w,
    output logic z
);
    typedef enum logic [1:0] {A, FIRST, SECOND, THIRD} phase_t;
    phase_t phase_r;
    logic [1:0] ones_r;

    always_ff @(posedge clk) begin
        if (reset) begin
            phase_r <= A;
            ones_r <= 2'd0;
            z <= 1'b0;
        end else begin
            z <= 1'b0;
            case (phase_r)
                A: begin
                    ones_r <= 2'd0;
                    if (s) phase_r <= FIRST;
                end
                FIRST: begin
                    ones_r <= {1'b0, w};
                    phase_r <= SECOND;
                end
                SECOND: begin
                    ones_r <= ones_r + {1'b0, w};
                    phase_r <= THIRD;
                end
                THIRD: begin
                    z <= ((ones_r + {1'b0, w}) == 2'd2);
                    ones_r <= 2'd0;
                    phase_r <= FIRST;
                end
                default: begin
                    phase_r <= A;
                    ones_r <= 2'd0;
                end
            endcase
        end
    end
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
module dev_tb;
    logic clk=0, reset=0, s=0, w=0;
    wire z;
    TopModule dut(.clk(clk), .reset(reset), .s(s), .w(w), .z(z));
    always #5 clk=~clk;
    bit active=0;
    bit samples[0:2];
    bit expected=0;
    integer n=0, checks=0, total;
    integer a,b,i,j;
    logic [31:0] rng=32'h81234567;
    task automatic step(input bit rst, input bit ss, input bit ww);
        @(negedge clk);
        reset=rst; s=ss; w=ww;
        #1;
        if (z "'!== expected) $fatal(1,"Output changed between edges");
        @(posedge clk);
        expected=0;
        if (rst) begin active=0; n=0; end
        else if (!active) begin
            if(ss) begin active=1; n=0; end
        end else begin
            samples[n]=ww;
            n=n+1;
            if(n==3) begin
                total=0;
                for(integer k=0;k<3;k=k+1) if(samples[k]) total=total+1;
                expected=(total==2);
                n=0;
            end
        end
        #1;
        checks=checks+1;
        if(z !== expected) $fatal(1,"Mismatch check=%0d expected=%b actual=%b",checks,expected,z);
    endtask
    initial begin
        step(1,0,0);
        for(i=0;i<8;i=i+1) step(0,0,i[0]);
        for(a=0;a<8;a=a+1) begin
            for(b=0;b<8;b=b+1) begin
                step(1,0,0);
                step(0,1,1);
                for(i=0;i<3;i=i+1) step(0,i[0],(a>>i)&1);
                for(i=0;i<3;i=i+1) step(0,0,(b>>i)&1);
                step(0,1,0);
            end
        end
        for(j=0;j<4;j=j+1) begin
            step(1,1,1); step(0,1,0);
            for(i=0;i<j;i=i+1) step(0,0,i<2);
            step(1,1,1); step(0,0,1); step(0,1,1);
            step(0,0,1); step(0,0,1); step(0,0,0);
            step(1,0,0);
        end
        for(i=0;i<3000;i=i+1) begin
            rng=rng ''^ (rng<<13); rng=rng ''^ (rng>>17); rng=rng ''^ (rng<<5);
            step(rng[7:2]==0,rng[0],rng[1]);
        end
        $display("PASS: %0d cycle and between-edge checks",checks);
        $finish;
    end
    initial begin #100000; $fatal(1,"Testbench timeout"); end
endmodule
EOF
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > dev_compile.log 2>&1
printf '"'compile_exit=%s\\n' \""'$?"
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > dev_simulation.log 2>&1
printf '"'simulation_exit=%s\\n' \""'$?"
cat dev_compile.log dev_simulation.log'

